using Purview.Unions;

namespace Purview.Results.Examples.Unions;

/// <summary>
/// The expected failures of a tenant operation, generated by <c>Purview.Unions</c>.
/// </summary>
/// <remarks>
/// <para>
/// <see cref="GenerateUnionAttribute"/> names the cases in its <c>typeof</c> list. The union generator emits
/// the <c>[Union]</c> attribute, one typed field and public constructor per case, <c>Value</c>,
/// <c>HasValue</c> and a non-boxing <c>TryGetValue</c> per case, so construction and pattern matching never
/// box a value-type case.
/// </para>
/// <para>
/// <c>[GenerateResult]</c> runs in the same compilation and reads that source-visible <c>typeof</c> list —
/// generators never see each other's output — so it emits the per-case <c>AsFailure&lt;TValue&gt;()</c> and
/// <c>AsFailure()</c> helpers and the union-receiver <c>TenantError.Failure(...)</c>/
/// <c>TenantError.Success(...)</c> factories without <c>Purview.Results</c> depending on
/// <c>Purview.Unions</c>.
/// </para>
/// </remarks>
[GenerateUnion(typeof(TenantNotFound), typeof(TenantDisabled), typeof(TenantAlreadyExists))]
[GenerateResult]
readonly partial struct TenantError;

/// <summary>
/// The requested tenant does not exist.
/// </summary>
/// <param name="TenantId">The identifier of the tenant.</param>
readonly record struct TenantNotFound(TenantId TenantId);

/// <summary>
/// The requested tenant exists but is disabled.
/// </summary>
/// <param name="TenantId">The identifier of the tenant.</param>
readonly record struct TenantDisabled(TenantId TenantId);

/// <summary>
/// A tenant with the requested identifier already exists.
/// </summary>
/// <param name="TenantId">The identifier of the tenant.</param>
readonly record struct TenantAlreadyExists(TenantId TenantId);
